"use server";

import { logActionError } from "@/lib/log-action-error";
import { getCookies } from "../../cookies";
import { apiFetch } from "@/lib/api-fetch";

interface TemplateResponse {
  success: boolean;
  message?: string;
  base64Data?: string;
  filename?: string;
  mimeType?: string;
}

/**
 * The spreadsheet model, fetched through the server action so the access token
 * never has to reach the browser.
 *
 * The file is generated by the API from the same column list the importer
 * reads, so it cannot drift from the parser — which is exactly why it is
 * downloaded rather than shipped as a static asset in this repo.
 */
const downloadImportTemplate = async (): Promise<TemplateResponse> => {
  const tokenAccess = await getCookies("tkey");

  if (!tokenAccess) {
    return {
      success: false,
      message: "Token de acesso não encontrado. Faça login novamente.",
    };
  }

  try {
    const response = await apiFetch(
      `${process.env.HTTP_REQUEST}/import/download-template`,
      {
        credentials: "include",
        method: "GET",
        headers: { Authorization: `Bearer ${tokenAccess}` },
        cache: "no-store",
      },
    );

    if (!response.ok) {
      return {
        success: false,
        message: "Não foi possível baixar o modelo de planilha.",
      };
    }

    const contentDisposition = response.headers.get("content-disposition");

    const filename =
      contentDisposition?.split("filename=")[1]?.replace(/"/g, "") ??
      "modelo-importacao-trajetto.xlsx";

    const arrayBuffer = await response.arrayBuffer();

    return {
      success: true,
      base64Data: Buffer.from(arrayBuffer).toString("base64"),
      filename,
      mimeType:
        response.headers.get("content-type") ??
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    };
  } catch (error) {
    logActionError("import/download-template", error);
    return {
      success: false,
      message: "Ocorreu um erro inesperado ao baixar o modelo.",
    };
  }
};

export { downloadImportTemplate };
export type { TemplateResponse };
